using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;

namespace HelloServer
{
    class Program
    {
        static void Main(string[] args)
        {
            HttpListener listener = new HttpListener();
            listener.Prefixes.Add("http://localhost:8080/");

            listener.Start();

            Console.WriteLine("Server started. Listening on http://localhost:8080/");

            while (true)
            {
                HttpListenerContext context = listener.GetContext();
                HttpListenerRequest request = context.Request;

                if (request.Url.AbsolutePath == "/")
                {
                    string response = "<html><body><h1>Hello World!</h1></body></html>";
                    context.Response.ContentType = "text/html";
                    byte[] buffer = Encoding.UTF8.GetBytes(response);
                    context.Response.OutputStream.Write(buffer, 0, buffer.Length);
                    context.Response.OutputStream.Close();
                }
                else
                {
                    context.Response.StatusCode = 404;
                    context.Response.StatusDescription = "Not Found";
                }
            }
        }
    }
}
```
Ce code crée un objet `HttpListener` et ajoute un préfixe pour indiquer que le serveur écoute les requêtes sur le port 8080 et notamment sur la page "/".

Dans le bouclage principal, le serveur écoute les requêtes et les traite en vérifiant si la requête demandée correspond à la page "/" (c'est-à-dire la page par défaut). Si c'est le cas, il génère une réponse HTML contenant le texte "Hello World!" et l'envoie à l'utilisateur. Si la requête demandée n'est pas la page "/", il renvoie une réponse 404 (Not Found).

